import{_ as t,o as a,c as i,a0 as n}from"./chunks/framework.CBux2OW7.js";const g=JSON.parse('{"title":"System Design Document (SDD) — Techy News","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),r={name:"guide/architecture.md"};function o(s,e,l,c,d,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="system-design-document-sdd-—-techy-news" tabindex="-1">System Design Document (SDD) — Techy News <a class="header-anchor" href="#system-design-document-sdd-—-techy-news" aria-label="Permalink to &quot;System Design Document (SDD) — Techy News&quot;">​</a></h1><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>Techy News is an AI-native Content Management System (CMS) and news aggregator designed for high-performance developer journalism. It automates the entire content lifecycle: from raw RSS signal ingestion to multi-lingual, deeply researched technical long-form articles.</p><h2 id="_2-core-architecture" tabindex="-1">2. Core Architecture <a class="header-anchor" href="#_2-core-architecture" aria-label="Permalink to &quot;2. Core Architecture&quot;">​</a></h2><h3 id="_2-1-backend-laravel-13" tabindex="-1">2.1 Backend (Laravel 13) <a class="header-anchor" href="#_2-1-backend-laravel-13" aria-label="Permalink to &quot;2.1 Backend (Laravel 13)&quot;">​</a></h3><p>The backend serves as the orchestration layer for AI services and data persistence.</p><ul><li><strong>Service Layer Pattern</strong>: All business logic is encapsulated in <code>app/Services</code>. <ul><li><code>NewsService</code>: RSS aggregation and preprocessing.</li><li><code>GeminiService</code>: Core LLM orchestration (Drafting, Metadata, Translation).</li></ul></li><li><strong>Inertia.js</strong>: Bridges the gap between Laravel and React without the overhead of a client-side router (SPA) or a decoupled API.</li><li><strong>Database Architecture</strong>: MySQL 8.0+. <ul><li><code>Article</code> model: Stores raw HTML in the <code>content</code> column to maximize rendering speed.</li><li><code>translations</code>: A JSON column storing locale-specific overrides for title, summary, and content.</li></ul></li></ul><h3 id="_2-2-frontend-react-18-vite" tabindex="-1">2.2 Frontend (React 18 + Vite) <a class="header-anchor" href="#_2-2-frontend-react-18-vite" aria-label="Permalink to &quot;2.2 Frontend (React 18 + Vite)&quot;">​</a></h3><ul><li><strong>Styling</strong>: Tailwind CSS + Custom Utility classes.</li><li><strong>Interactions</strong>: Framer Motion for sophisticated, hardware-accelerated animations.</li><li><strong>Components</strong>: Functional React components with a focus on atomic design principles.</li><li><strong>Rich Text Rendering</strong>: <ul><li>Articles use a custom <code>TipTapRenderer</code> to parse ProseMirror-like JSON structures into semantic HTML.</li><li>Syntax highlighting is handled via <code>Prism.js</code> with dynamic language loading.</li><li>Mermaid.js is integrated for dynamic technical diagrams.</li></ul></li></ul><h2 id="_3-the-intelligence-pipeline" tabindex="-1">3. The Intelligence Pipeline <a class="header-anchor" href="#_3-the-intelligence-pipeline" aria-label="Permalink to &quot;3. The Intelligence Pipeline&quot;">​</a></h2><h3 id="_3-1-signal-ingestion" tabindex="-1">3.1 Signal Ingestion <a class="header-anchor" href="#_3-1-signal-ingestion" aria-label="Permalink to &quot;3.1 Signal Ingestion&quot;">​</a></h3><p>The system periodically polls high-signal tech RSS feeds (TechCrunch, Hacker News, The Verge). These are aggregated and deduplicated.</p><h3 id="_3-2-automated-synthesis" tabindex="-1">3.2 Automated Synthesis <a class="header-anchor" href="#_3-2-automated-synthesis" aria-label="Permalink to &quot;3.2 Automated Synthesis&quot;">​</a></h3><p>When a &quot;Synthesis&quot; event is triggered:</p><ol><li><strong>Idea Generation</strong>: Gemini analyzes headlines to find unique editorial angles.</li><li><strong>Drafting</strong>: The AI generates a 1500-2000 word investigative piece using a &quot;Blueprint Prompting&quot; technique.</li><li><strong>Metadata Generation</strong>: SEO tags, summaries, and reading times are generated in a post-processing pass.</li></ol><h3 id="_3-3-the-translation-engine" tabindex="-1">3.3 The Translation Engine <a class="header-anchor" href="#_3-3-the-translation-engine" aria-label="Permalink to &quot;3.3 The Translation Engine&quot;">​</a></h3><p>A recursive unwrapping strategy is used to handle AI-generated content.</p><ul><li><strong>Recursive Decoding</strong>: AI models occasionally return JSON-encoded strings (e.g., <code>&quot;&lt;h2&gt;Title&lt;/h2&gt;&quot;</code>). The backend recursively decodes these until raw HTML is extracted.</li><li><strong>Heuristic Cleanup</strong>: Strips unnecessary slashes and wrapping quotes to ensure DB-ready HTML.</li></ul><h2 id="_4-performance-optimization" tabindex="-1">4. Performance &amp; Optimization <a class="header-anchor" href="#_4-performance-optimization" aria-label="Permalink to &quot;4. Performance &amp; Optimization&quot;">​</a></h2><h3 id="_4-1-caching-strategy" tabindex="-1">4.1 Caching Strategy <a class="header-anchor" href="#_4-1-caching-strategy" aria-label="Permalink to &quot;4.1 Caching Strategy&quot;">​</a></h3><ul><li><strong>Layered Cache</strong>: <ul><li>Homepage Grid: 1 hour.</li><li>Daily AI Brief: 24 hours.</li><li>Article Views: 1 hour (per locale).</li></ul></li><li><strong>Pre-translation</strong>: When an article is requested in one language, the system opportunistically translates and caches it in mandatory locales (EN, ES) to reduce future latency.</li></ul><h3 id="_4-2-asset-pipeline" tabindex="-1">4.2 Asset Pipeline <a class="header-anchor" href="#_4-2-asset-pipeline" aria-label="Permalink to &quot;4.2 Asset Pipeline&quot;">​</a></h3><ul><li><strong>Vite 6</strong>: Optimized bundling with automatic code splitting for Inertia pages.</li><li><strong>CDN Strategy</strong>: Heavy libraries like Prism.js and Mermaid.js are loaded via high-availability CDNs to keep initial bundle sizes minimal.</li></ul><h2 id="_5-security-stability" tabindex="-1">5. Security &amp; Stability <a class="header-anchor" href="#_5-security-stability" aria-label="Permalink to &quot;5. Security &amp; Stability&quot;">​</a></h2><ul><li><strong>CSRF Protection</strong>: Native Laravel middleware via Inertia.</li><li><strong>Rate Limiting</strong>: Integrated 10s back-off for Gemini API calls to prevent 429 errors.</li><li><strong>Environment Isolation</strong>: Production deployments via GitHub Actions ensure a clean build and automated test suite execution.</li></ul>',25)])])}const m=t(r,[["render",o]]);export{g as __pageData,m as default};
